def page_of(value: object, query: dict[str, str], state: dict[str, Any], page: int) -> object:
    """Return one page of a list value, or the value itself when it is not a list."""
    wrapped = isinstance(value, dict) and "list_key" in value
    items = value["items"] if wrapped else value
    if not isinstance(items, list):
        return value
    per_page = int(query.get("per_page") or state.get("per_page") or DEFAULT_PER_PAGE)
    chunk = items[(page - 1) * per_page : page * per_page]
    if wrapped:
        return {"total_count": len(items), value["list_key"]: chunk}
    return chunk


def page_count(value: object, query: dict[str, str], state: dict[str, Any]) -> int:
    """Return how many pages a list value spans."""
    items = value["items"] if isinstance(value, dict) and "list_key" in value else value
    if not isinstance(items, list):
        return 1
    per_page = int(query.get("per_page") or state.get("per_page") or DEFAULT_PER_PAGE)
    return max(1, -(-len(items) // per_page))


